/** Bundle the web's pure inference model for the local quickjs-ng and Node hosts. */
import { fileURLToPath } from "node:url";
import { readFile } from "node:fs/promises";
import path from "node:path";
import { build } from "vite";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const output = path.resolve(root, "../../.agents/skills/ncp-damage-calculator/scripts");
const file = "inference_core.bundle.js";
const check = process.argv.includes("--check");
// Rolldown's region labels are relative to cwd; keep the generated bytes checkout-independent.
process.chdir(root);

const result = await build({
  configFile: false,
  root,
  publicDir: false,
  build: {
    lib: {
      entry: path.join(root, "src/pages/calc/infer/shared_runtime.ts"),
      name: "QuarkInferenceCore",
      formats: ["iife"],
      fileName: () => file,
    },
    outDir: output,
    emptyOutDir: false,
    minify: false,
    sourcemap: false,
    write: !check,
  },
});

if (check) {
  const outputs = Array.isArray(result) ? result : [result];
  const chunk = outputs.flatMap((entry) => entry.output).find((entry) => entry.fileName === file);
  const existing = await readFile(path.join(output, file), "utf8");
  if (!chunk || chunk.code.replace(/\r\n/g, "\n") !== existing.replace(/\r\n/g, "\n")) {
    throw new Error(`${file} is stale; rebuild the inference core`);
  }
  process.stdout.write(`${file} matches source\n`);
}
